theorem cardinality_of_A : 
    let n : ℤ := 0; 
    let k : ℤ := 0; 
    let p : ℤ := 0; 
    let v_p : ℤ → ℤ := fun _ => 0; 
    let F : ℤ → ℤ := fun m => ∏ j in Finset.Icc 1 m, (j : ℤ); 
    let P : ℤ := ∏ i in Finset.Icc 1 9, F i; 
    let A : Set ℤ := { s | s > 0 ∧ (s^2 : ℤ) ∣ P } in 
    Finset.card (A : Set ℤ).toFinite.toFinset = 672 := sorry

theorem count_solutions_eq_two : 
    let f : ℝ → ℝ := fun x => Real.sin ((π / 2) * Real.cos x)
    let g : ℝ → ℝ := fun x => Real.cos ((π / 2) * Real.sin x)
    in Finset.card (Finset.filter (fun x => f x = g x) (Set.Icc (0 : ℝ) π).toFinset) = 2 := sorry

theorem count_solutions : 
    let x : ℝ := x; 
    hx_nonneg : 0 ≤ x := by
      intro hx_nonneg;
    hx_le : x ≤ 2 * π := by
      intro hx_le;
    f : ℝ → ℝ := λ x => Real.tan (2 * x);
    g : ℝ → ℝ := λ x => Real.cos (x / 2);
    h1 : ∀ x : ℝ, ¬∃ k : ℤ, 2 * x = π / 2 + k * π := by
      intro h1;
    h2 : ∀ x : ℝ, ¬∃ k : ℤ, 2 * x = -π / 2 + k * π := by
      intro h2;
    in
    Finset.card (Finset.filter (λ x => f x = g x) (Set.Icc (0 : ℝ) (2 * π)).toFinset) = 5 := sorry
